There exists constant $\hyperlink{DBconst}{C_{(19)}} > 0$ and $n_0 \in \mathbb{N}$ such that for all $\mathbf{u}_n \in \mathbb{X}_n$ and $n > n_0$, it holds that
   \begin{equation} 
      \Vert \rho^{1/2} \mathbf{D}_{\mathbf{b}}^n (P_{V_n} \mathbf{u}_n) \Vert^2_{\mathcal{T}_n} \le \hypertarget{DBconst} \hyperlink{DBconst}{C_{(19)}} \Vert c_s^{-1} \mathbf{b} \Vert_{\mathbf{L}^\infty}^2 \vert S_n \mathbf{u}_n \vert_{{\mathbf H}^1_{c_s^2\rho}}^2.
   \end{equation}
   In particular, $\hyperlink{DBconst}{C_{(19)}} = 1 + O(h_n^2)$.

For any $\delta \in (0,1)$, there exist $C_{\delta} > 0$, so that
   \begin{equation}
      \begin{aligned}
         \!\!\Vert c_s \rho^{1/2} \!\operatorname{div}_{\boldsymbol{\nu}}^n \! P_{V_n} \!\mathbf{u}_n \Vert^2_{\mathcal{T}_n} \! \ge \!\left(\! (1\!-\!\delta)^2 \vert S_n \mathbf{u}_n \vert^2_{{\mathbf H}^1_{c_s^2 \rho}} \! \! \! \! \! - C_{\delta} \Vert S_n \mathbf{u}_n \Vert^2_{\mathbf{L}^2} \!\right) \! + \! \langle \check{O}_n \mathbf{u}_n, \!\mathbf{u}_n \rangle_{\mathbb{X}_n}\!,\!\!\!
      \end{aligned}
   \end{equation}
   for all $\mathbf{u}_n\in\mathbb{X}_n$ and $\lim_{n \to \infty} \Vert \check{O}_n \Vert_{L(\mathbb{X}_n)} = 0$.

Assume that there exists a constant $C>0$, sequences $(A_n)_{n \in \mathbb{N}}$, $(T_n)_{n \in \mathbb{N}}$, $(B_n)_{n \in \mathbb{N}}$, $(K_n)_{n \in \mathbb{N}}$ and $B,T \in L(X)$ such that for each $n \in \mathbb{N}$ it holds that $A_n,T_n,B_n,K_n \in L(X_n)$, $\Vert T_n \Vert_{L(X_n)}$, $\Vert T_n^{-1} \Vert_{L(X_n)}$, $\Vert B_n \Vert_{L(X_n)}$, $\Vert B_n^{-1} \Vert_{L(X_n)} \le C$, $B$ is bijective, $(K_n)_{n \in \mathbb{N}}$ is \hyperlink{compactop}{compact}~and 
   \begin{equation*}
      \lim_{n \rightarrow \infty} \Vert T_n p_n u - p_n T u \Vert_{X_n} = 0, \qquad \lim_{n \rightarrow \infty} \Vert B_n p_n u - p_n B u \Vert_{X_n} = 0, \qquad \forall u \in X,
   \end{equation*} 
   \begin{equation*}
      A_n T_n = B_n + K_n. 
   \end{equation*}
   Then the sequence $(A_n)_{n \in \mathbb{N}}$ is \hyperlink{regular}{regular}.
